  // Network: adcombo/cpalead/alfaleads
  // Geo: {{geo}}
  // Vertical: {{vertical}}
  // Min payout: {{min_payout}}

  await navigate({url: "https://adcombo.com/offers?geo={{geo}}&vertical={{vertical}}&min_payout={{min_payout}}"})
  await wait({for: "selector", value: ".offer-card"})

  const snap = await snapshot()
  const offers = []

  for (const ref of snap.refs) {
    if (ref.text.includes("offer") || ref.text.includes("payout")) {
      await click({ref: ref.ref})
      await wait({for: "selector", value: ".offer-details"})
      const detail = await read({format: "markdown"})
      offers.push(detail)
      await navigate({url: "https://adcombo.com/offers?geo={{geo}}&vertical={{vertical}}&min_payout={{min_payout}}"})
      await wait({for: "selector", value: ".offer-card"})
